            {[1, 2, 3, 4, 5, 6].map((i) => (
              <div key={i} className={`p-4 rounded-[20px] border-2 border-[#47510B] flex items-center justify-between transition-all ${i <= 3 ? 'bg-white shadow-[4px_4px_0_0_#CAD23C] opacity-100' : 'bg-white/40 border-dashed opacity-50'}`}>
